{"python": "def pilot_policy(trace):
    if not trace:
        return None
    action, label = trace[-1]
    name = action.name
    args = json.loads(action.arguments)
    categories = label.subset
    allowed = {
        "slot:assessor": {"PRICING", "ACCESS"},
        "slot:escrow": {"ACCESS", "UNSCREENED"},
        "slot:oversight": {"UNSCREENED"},
        "slot:public": {"CUSTOMER", "PRICING", "ACCESS"},
        "slot:supplier": {"CUSTOMER", "ACCESS"}
    }
    if name in ["procurement/transfer_case", "compliance/transfer_case"]:
        team = "procurement" if "procurement" in name else "compliance"
        recipient = args.get("recipient")
        replica = args.get("replica")
        recipient_slot = None
        if team == "procurement":
            if recipient == "local":
                recipient_slot = "slot:operations"
            elif recipient == "partner":
                recipient_slot = "slot:supplier"
            elif recipient == "oversight":
                recipient_slot = "slot:public"
        else:
            if recipient == "local":
                recipient_slot = "slot:operations"
            elif recipient == "partner":
                recipient_slot = "slot:assessor"
            elif recipient == "oversight":
                recipient_slot = "slot:oversight"
        destinations = set()
        if recipient_slot:
            destinations.add(recipient_slot)
        if replica == "escrow":
            destinations.add("slot:escrow")
        elif replica == "public":
            destinations.add("slot:public")
        elif replica == "partner":
            if team == "procurement":
                destinations.add("slot:supplier")
            else:
                destinations.add("slot:assessor")
        for slot in destinations:
            if slot in allowed and not categories.issubset(allowed[slot]):
                raise PolicyViolation(f"Categories {categories} not allowed in {slot}")
        return None
    else:
        return None"}
